var utils = require('./utils'),
    render = utils.render;

describe('fest:choose', function () {

    beforeEach(utils.setupMatchers);

    it('should provide if-then-else flow', function () {
        expect(
            render('templates/choose.xml').contents
        ).toBe(
            'truechoose'
        );
    });

    it('should throw exception if fest:when contains syntax error in test attribute', function () {
        expect(function () {
            render('templates/choose_with_error_in_test.xml');
        }).toThrowMatch(
            /At line 4: attribute "test" has SyntaxError: Unexpected token ILLEGAL/
        );
    });

});

var utils = require('./utils'),
    render = utils.render;

describe('fest:if', function () {

    beforeEach(utils.setupMatchers);

    it('should render truthful blocks only', function () {
        expect(
            render('templates/if.xml').contents
        ).toBe(
            'truetrue&'
        );
    });

    it('should throw exception if fest:if contains syntax error in test attribute', function () {
        expect(function () {
            render('templates/if_with_error_in_test.xml');
        }).toThrowMatch(
            /At line 3: attribute "test" has SyntaxError: Unexpected token ILLEGAL/
        );
    });

});

var utils = require('./utils'),
    render = utils.render;

describe('fest:include', function () {

    beforeEach(utils.setupMatchers);

    it('should transparently include files', function () {
        expect(
            render('templates/include.xml', {list: [[1, 2, 3], [4, 5, 6]]}).contents
        ).toBe(
            '123456'
        );
    });

    it('should throw exception if fest:include contains syntax error in context attribute', function () {
        expect(function () {
            render('templates/include_with_error_in_context.xml');
        }).toThrowMatch(
            /At line 3: attribute "context" has SyntaxError: Unexpected token ILLEGAL/
        );
    });

});

var utils = require('./utils'),
    render = utils.render;

describe('Other errors', function () {

    beforeEach(utils.setupMatchers);

    it('should render empty string if file does not exist', function () {
        var result = render('templates/errors.xml');
        expect(
            result.contents
        ).toBe('');
        expect(
            result.errors
        ).toMatchEach([
            /error open file/
        ]);
    });

    it('should throw XML errors in strict mode', function () {
        expect(function () {
            render('templates/strict_error.xml');
        }).toThrowMatch(
            /At line 3: Error: Attribute without value/
        );
    });

});

var utils = require('./utils'),
    render = utils.render;

describe('fest:template', function () {

    beforeEach(utils.setupMatchers);

    it('should throw exception if fest:template is not closed', function () {
        expect(function () {
            render('templates/template_with_unclosed_error.xml');
        }).toThrowMatch(
            /At line 2: fest:template is not closed/
        );
    });

    it('should throw exception if the template is not well-formed', function () {
        expect(function () {
            render('templates/template_with_invalid_xml_error.xml');
        }).toThrowMatch(
            /Unexpected close tag/
        );
    });

});

var utils = require('./utils'),
    render = utils.render;

describe('fest:script', function () {

    beforeEach(utils.setupMatchers);

    it('should compile scrpt AS-IS', function () {
        expect(
            render('templates/script.xml', {}).contents
        ).toBe(
            '"true""true&quot;"'
        );
    });

    it('should throw exception if fest:script contains syntax error', function () {
        expect(function () {
            render('templates/include_with_error_in_context.xml');
        }).toThrowMatch(
            /At line 3: attribute "context" has SyntaxError: Unexpected token ILLEGAL/
        );
    });

    it('should ignore non-strict fest:script', function () {
        var result = render('templates/strict.xml', {});
        expect(
            result.contents
        ).toBe(
            'true'
        );
        expect(
            result.errors
        ).toMatchEach([
            /g is not defined/
        ]);
    });

});

var utils = require('./utils'),
    render = utils.render;

describe('fest:value', function () {

    beforeEach(utils.setupMatchers);

    it('should escape control characters', function () {
        expect(
            render('templates/value.xml', { 'value': 'value', 's' : '</script>' }).contents
        ).toBe(
            'valuevalue<script/>true\\"|\\\'\\u003Cscript\\/\\u003E"\\u003C\/script\\u003E""value"'
        );
    });

    it('should suppress XSS', function () {
        expect(
            render('templates/xss.xml', { xss: "\\x22\\x3Ealert\\x28document.cookie\\x29\\x3C\\x2fscript\\x3E" }).contents
        ).toBe(
            '<script>document.write(\'<script id="\\\\x22\\\\x3Ealert\\\\x28document.cookie\\\\x29\\\\x3C\\\\x2fscript\\\\x3E">\');</script>'
        );
    });

});

var utils = require('./utils'),
    render = utils.render;

describe('fest:plural', function () {

    beforeEach(utils.setupMatchers);

    it('should plural russian', function () {
        expect(
            render('templates/plural.xml', {
                n1: 1,
                n2: 23,
                n3: 166
            }).contents
        ).toBe(
            'один рубль|23 рубля|166 рублей'
        );
    });

    it('should plural english', function () {
        expect(
            render('templates/plural_english.xml', {
                n1: 1,
                n2: 23,
                n3: 166
            }).contents
        ).toBe(
            'one ruble|23 rubles|166 rubles'
        );
    });


    it('should escape control characters', function () {
        expect(
            render('templates/plural_escape.xml', {
                n1: 1,
                n2: 23
            }).contents
        ).toBe(
            '|%1%s|,|%23%s|'
        );
    });

    it('should throw exception if the template has inconsistent number of plural forms', function () {
        expect(function () {
            render('templates/plural_with_error.xml', {
                n1: 1,
                n2: 23
            });
        }).toThrowMatch(
            /At line 4: inconsistent number of plural forms in "ruble|rubles" (expected 3 but got 2)/
        );
    });

});

