    render = utils.render;

describe('fest:each', function () {

    beforeEach(utils.setupMatchers);

    it('should iterate through objects', function () {
        expect(
            render('templates/each.xml').contents
        ).toBe(
            'foo=barfoo=bar'
        );
    });

    it('should throw exception if fest:each contains syntax error in iterate attribute', function () {
        expect(function () {
            render('templates/each_with_error_in_iterate.xml');
        }).toThrowMatch(
            /At line 3: attribute "iterate" has SyntaxError: Unexpected token ILLEGAL/
        );
    });

    it('should throw exception if fest:each contains syntax error in index attribute', function () {
        expect(function () {
            render('templates/each_with_error_in_index.xml');
        }).toThrowMatch(
            /At line 3: attribute "index" has an invalid identifier/
        );
    });

    it('should throw exception if fest:each contains syntax error in value attribute', function () {
        expect(function () {
            render('templates/each_with_error_in_value.xml');
        }).toThrowMatch(
            /At line 3: attribute "value" has an invalid identifier/
        );
    });

});

var utils = require('./utils'),
    render = utils.render;

describe('fest:element', function () {

    beforeEach(utils.setupMatchers);

    it('should support nested elements', function () {
        var result = render('templates/element.xml');
        expect(
            result.contents
        ).toBe(
            '<div class="foo bar"></div><div><i></i></div><div>foo</div><hr/><img src="foo"/><div><span>foo</span>bar<br/><div class="foo"></div></div><div></div><div></div><span></span><div></div><span>login</span><table>table code</table><div>expr code</div><div>div code</div>'
        );
        expect(
            result.errors
        ).toMatchEach(
            [
                /name4 is not defined/,
                /nameX is not defined/,
                /Element name must be a string/,
                /variable2 is not defined/
            ]
        );
    });

    it('should throw exception if fest:element contains syntax error in select attribute', function () {
        expect(function () {
            render('templates/element_with_error_in_select.xml');
        }).toThrowMatch(
            /At line 3: attribute "select" has SyntaxError: Unexpected token ILLEGAL/
        );
    });

    it('should throw exception if fest:element contains syntax error in expression in name attribute', function () {
        expect(function () {
            render('templates/element_with_syntax_error_in_name.xml');
        }).toThrowMatch(
            /At line 3: expression #1 in attribute "name" has SyntaxError: Unexpected token \)/
        );
    });

});

var utils = require('./utils'),
    render = utils.render;

describe('fest:var', function () {

    beforeEach(utils.setupMatchers);

    it('should set local variables', function () {
        expect(
            render('templates/var.xml').contents
        ).toBe(
            '4284'
        );
    });

    it('should throw exception if fest:var contains syntax error in select attribute', function () {
        expect(function () {
            render('templates/var_with_error_in_select.xml');
        }).toThrowMatch(
            /At line 3: attribute "select" has SyntaxError: Unexpected token ?/
        );
    });

    it('should throw exception if fest:var contains fest:set, fest:get or fest:include', function () {
        expect(function () {
            render('templates/var_with_get_block_error.xml');
        }).toThrowMatch(
            /At line 4: fest:get is not allowed inside fest:var/
        );
        expect(function () {
            render('templates/var_with_set_block_error.xml');
        }).toThrowMatch(
            /At line 4: fest:set is not allowed inside fest:var/
        );
        expect(function () {
            render('templates/var_with_include_error.xml');
        }).toThrowMatch(
            /At line 4: fest:include is not allowed inside fest:var/
        );
    });

});

